  const container = document.querySelector('.breed-results-comparison');
  if (!container) return null;

  // Let's get the header cells (breeds)
  const headerCells = Array.from(container.querySelectorAll('.breed-results-comparison__cell_heading-image'));
  const breeds = headerCells.map(cell => {
    const closeBtn = cell.querySelector('.breed-results-comparison-image-close');
    const id = closeBtn ? closeBtn.getAttribute('data-id') : null;
    const img = cell.querySelector('img:not([src*="icon"])');
    return {
      id,
      imgSrc: img ? img.src : null
    };
  });

  // Let's map ids to breed names:
  // 23414 = Azawakh
  // 23239 = Akita
  // 23209 = Afghan Hound

  // Now let's get all rows in the comparison table
  const rows = Array.from(container.querySelectorAll('.breed-results-comparison__row'));
  const rowData = rows.map((row, rIdx) => {
    const titleEl = row.querySelector('.breed-results-comparison__title, .breed-results-comparison__cell_title, h3, h4');
    const cells = Array.from(row.querySelectorAll('.breed-results-comparison__cell'));
    return {
      rIdx,
      rowClass: row.className,
      cells: cells.map(c => ({
        className: c.className,
        text: c.innerText.trim(),
        html: c.innerHTML.trim()
      }))
    };
  });

  return {
    breeds,
    rowsCount: rows.length,
    rowData
  };
});

