const tabId = 1962625065;
const fullTable = await browserjs(tabId, () => {
  const container = document.querySelector('.breed-results-comparison');
  if (!container) return null;

  const rows = Array.from(container.querySelectorAll('.breed-results-comparison__row'));

  let currentTitle = "";
  const result = [];

  for (const row of rows) {
    // Check if it's a title row
    if (row.classList.contains('breed-results-comparison__row-title')) {
      const text = row.innerText.trim();
      if (text) {
        currentTitle = text;
      }
      continue;
    }

    const cells = Array.from(row.querySelectorAll('.breed-results-comparison__cell'));
    if (cells.length === 0) continue;

    // Check if this row has subheadings or labels inside cells
    const cellData = cells.map(cell => {
      // Check for rating / scale (e.g. svg, active dots, or text)
      const scaleVal = cell.querySelector('.breed-results-comparison__scale, [class*="scale"], [class*="rating"]');
      const score = cell.getAttribute('data-score') || cell.querySelector('[data-score]')?.getAttribute('data-score');
      return {
        text: cell.innerText.trim().replace(/\n+/g, ' | '),
        score: score || null,
        html: cell.innerHTML.trim()
      };
    });

    result.push({
      sectionTitle: currentTitle,
      cells: cellData
    });
  }

  return result;
});

console.log("Extracted items:", fullTable.length);
console.log(JSON.stringify(fullTable, null, 2));

